"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[2670],{2670(e,s,n){n.d(s,{content:()=>l,description:()=>r,keywords:()=>a,title:()=>t});n(5043);var i=n(579);const t="Labo Virtuel de Physique : Simulations qui Enseignent",r="Pourquoi la physique est id\xe9alement adapt\xe9e \xe0 la simulation, ce qui rend les mauvaises simulations de physique nuisibles, et comment un moteur physiquement pr\xe9cis transforme l'apprentissage.",a="laboratoire virtuel de physique, simulation de physique, exp\xe9riences de physique en ligne, travaux pratiques de physique, simulation de m\xe9canique, simulation de forces",l=(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("p",{children:"La physique a la r\xe9putation d'\xeatre l'une des sciences les plus difficiles. Concepts abstraits, forces invisibles, \xe9quations qui semblent d\xe9connect\xe9es de la r\xe9alit\xe9. Pourtant, la physique est aussi la science la plus parfaitement adapt\xe9e \xe0 la simulation informatique. Quand un moteur de simulation capture correctement la physique, les \xe9l\xe8ves n'apprennent pas seulement les lois de Newton. Ils les vivent."}),(0,i.jsx)("p",{children:"Le probl\xe8me est que la plupart des simulations de physique ne le font pas correctement. Et quand elles le font mal, les \xe9l\xe8ves apprennent de mauvaises intuitions. C'est pire que de ne pas utiliser de simulations du tout."}),(0,i.jsx)("h2",{children:"Pourquoi la physique est unique pour la simulation"}),(0,i.jsx)("p",{children:"Voici ce qui rend la physique sp\xe9ciale : la m\xe9canique newtonienne peut \xeatre mod\xe9lis\xe9e exactement. Pas approximativement. Exactement. Les \xe9quations qui r\xe9gissent le mouvement, les forces, l'\xe9nergie et la quantit\xe9 de mouvement sont d\xe9terministes. Avec les m\xeames conditions initiales, on obtient les m\xeames r\xe9sultats \xe0 chaque fois."}),(0,i.jsxs)("p",{children:["La recherche en didactique de la physique confirme cet avantage. Les \xe9tudes montrent que les simulations interactives de physique produisent une compr\xe9hension conceptuelle significativement meilleure que l'enseignement traditionnel seul (",(0,i.jsx)("a",{href:"https://doi.org/10.1119/1.2150754",target:"_blank",rel:"noopener noreferrer",children:"Finkelstein et al., 2005"}),"). Quand les \xe9l\xe8ves peuvent manipuler des variables et voir imm\xe9diatement les cons\xe9quences, les concepts abstraits deviennent concrets."]}),(0,i.jsx)("p",{children:"Comparez cela \xe0 la chimie ou \xe0 la biologie. Les r\xe9actions chimiques impliquent des effets quantiques qui n\xe9cessitent une puissance de calcul massive pour \xeatre simul\xe9s avec pr\xe9cision. Les syst\xe8mes biologiques sont si complexes que m\xeame les superordinateurs ne peuvent qu'approximer leur comportement. Mais une balle roulant sur une rampe ? Un pendule oscillant ? Un circuit \xe9lectrique ? Ceux-ci peuvent \xeatre simul\xe9s parfaitement sur un ordinateur portable standard."}),(0,i.jsx)("p",{children:"Les exp\xe9riences de physique ont \xe9galement des entr\xe9es et sorties propres. Vous pouvez isoler compl\xe8tement les variables. Changer la masse tout en gardant la vitesse constante. Ajuster l'angle sans toucher au coefficient de frottement. Ce type d'exp\xe9rimentation contr\xf4l\xe9e est plus difficile avec des organismes vivants ou des r\xe9actions chimiques qui d\xe9pendent de dizaines de facteurs."}),(0,i.jsx)("p",{children:"La r\xe9p\xe9tabilit\xe9 compte aussi. Ex\xe9cutez la m\xeame simulation de physique cent fois et vous obtenez des r\xe9sultats identiques. Ce n'est pas un bug. C'est une fonctionnalit\xe9. Les \xe9l\xe8ves peuvent tester des hypoth\xe8ses, pr\xe9dire des r\xe9sultats et v\xe9rifier leurs pr\xe9dictions avec certitude. C'est la m\xe9thode scientifique rendue tangible."}),(0,i.jsx)("h2",{children:"Le probl\xe8me avec les mauvaises simulations de physique"}),(0,i.jsx)("p",{children:"Toutes les simulations ne se valent pas. Beaucoup de \xab simulations de physique \xbb \xe9ducatives ne sont pas du tout des simulations. Ce sont des animations qui pr\xe9tendent \xeatre des simulations."}),(0,i.jsx)("p",{children:"Voici la diff\xe9rence. Une animation rejoue une s\xe9quence pr\xe9enregistr\xe9e. Une simulation calcule ce qui se passe en temps r\xe9el en fonction des lois physiques. Quand vous laissez tomber une balle dans une animation, elle tombe \xe0 la vitesse que l'animateur a d\xe9cid\xe9 qui avait l'air bien. Quand vous laissez tomber une balle dans une simulation, elle acc\xe9l\xe8re \xe0 9,8 m/s\xb2 parce que c'est ce que fait la gravit\xe9."}),(0,i.jsxs)("p",{children:["Pourquoi est-ce important ? Parce que les \xe9l\xe8ves apprennent de ce qu'ils observent. Si l'animation montre une balle lourde tombant plus vite qu'une balle l\xe9g\xe8re (une id\xe9e fausse courante), les \xe9l\xe8ves int\xe9riorisent cette physique incorrecte. La recherche sur les conceptions erron\xe9es en enseignement de la physique montre que les intuitions incorrectes sont remarquablement persistantes une fois form\xe9es (",(0,i.jsx)("a",{href:"https://doi.org/10.1119/1.2343497",target:"_blank",rel:"noopener noreferrer",children:"Hestenes et al., 1992"}),"). Les mauvaises simulations n'\xe9chouent pas seulement \xe0 enseigner. Elles enseignent activement de mauvaises id\xe9es."]}),(0,i.jsx)("p",{children:"Les r\xe9sultats pr\xe9cuits sont un autre probl\xe8me. Certaines plateformes montrent ce qui \xab devrait \xbb arriver plut\xf4t que de calculer ce qui arriverait. Titr\xe9 trop vite ? La simulation montre quand m\xeame le bon changement de couleur. Connect\xe9 un circuit mal ? Il s'allume quand m\xeame. Les \xe9l\xe8ves terminent le TP sans d\xe9velopper de compr\xe9hension v\xe9ritable parce que la simulation les a prot\xe9g\xe9s de leurs propres erreurs."}),(0,i.jsx)("p",{children:"Les pires contrevenants sont les simulations avec des contraintes cach\xe9es. Un projectile qui se courbe myst\xe9rieusement pour atteindre la cible. Un frottement qui appara\xeet et dispara\xeet selon que la r\xe9ponse serait correcte. Ces rails invisibles guident les \xe9l\xe8ves vers la \xab bonne \xbb r\xe9ponse tout en contournant la vraie physique. C'est de la fraude p\xe9dagogique d\xe9guis\xe9e en apprentissage interactif."}),(0,i.jsx)("h2",{children:"Ce qu'un moteur physiquement pr\xe9cis fournit"}),(0,i.jsx)("p",{children:"Un vrai moteur de simulation physique calcule chaque interaction en utilisant de vraies \xe9quations. La gravit\xe9 fonctionne parce que le moteur calcule F = ma pour chaque objet \xe0 chaque image. Le frottement fonctionne parce que le moteur applique \u03bcN aux surfaces en contact. Les collisions fonctionnent parce que le moteur conserve la quantit\xe9 de mouvement et l'\xe9nergie selon la vraie physique."}),(0,i.jsx)("p",{children:"Cela importe pour plusieurs raisons. Premi\xe8rement, des r\xe9sultats surprenants se produisent naturellement. Un \xe9l\xe8ve pourrait s'attendre \xe0 ce que le chariot plus lourd acc\xe9l\xe8re plus vite quand on le pousse avec une force \xe9gale. La simulation montre le contraire. Ce moment de surprise, quand la r\xe9alit\xe9 contredit l'attente, c'est l\xe0 que l'apprentissage profond se produit."}),(0,i.jsx)("p",{children:"Deuxi\xe8mement, les erreurs ont des cons\xe9quences. Si vous c\xe2blez un circuit incorrectement, l'ampoule ne s'allume pas. Si vous installez la rampe au mauvais angle, la voiture n'atteint pas la cible. Ces cons\xe9quences ne sont pas des punitions programm\xe9es. Ce sont des r\xe9sultats naturels de la physique. Les \xe9l\xe8ves apprennent \xe0 diagnostiquer les probl\xe8mes en comprenant la physique, pas en devinant ce que veut le logiciel."}),(0,i.jsx)("p",{children:"Troisi\xe8mement, des mesures pr\xe9cises deviennent possibles. Quand la simulation utilise de la vraie physique, les nombres qu'elle produit sont significatifs. Les \xe9l\xe8ves peuvent mesurer l'acc\xe9l\xe9ration, calculer les forces, v\xe9rifier la conservation de l'\xe9nergie. Les comp\xe9tences d'analyse de donn\xe9es se transf\xe8rent directement au travail de laboratoire r\xe9el."}),(0,i.jsxs)("p",{children:["La recherche confirme ces avantages. Une revue exhaustive des simulations de physique a trouv\xe9 que la pr\xe9cision du mod\xe8le sous-jacent \xe9tait le pr\xe9dicteur le plus fort des r\xe9sultats d'apprentissage (",(0,i.jsx)("a",{href:"https://doi.org/10.1103/PhysRevPhysEducRes.13.010124",target:"_blank",rel:"noopener noreferrer",children:"de Jong et al., 2013"}),"). La fid\xe9lit\xe9 compte."]}),(0,i.jsx)("h2",{children:"Exemples pratiques : Exp\xe9riences de physique qui fonctionnent"}),(0,i.jsx)("p",{children:"Regardons des exp\xe9riences sp\xe9cifiques o\xf9 la simulation physiquement pr\xe9cise excelle."}),(0,i.jsx)("h3",{children:"Forces et mouvement"}),(0,i.jsx)("p",{children:"Les lois de Newton sont fondamentales mais abstraites. F = ma est facile \xe0 \xe9crire et difficile \xe0 vraiment comprendre. Dans une simulation physiquement pr\xe9cise, les \xe9l\xe8ves peuvent appliquer des forces \xe0 des objets et observer leur acc\xe9l\xe9ration directement. Ils peuvent ajouter de la masse et voir l'acc\xe9l\xe9ration diminuer. Ils peuvent \xe9quilibrer les forces et observer les objets rester stationnaires ou se d\xe9placer \xe0 vitesse constante."}),(0,i.jsx)("p",{children:"La puissance vient de la manipulation. Que se passe-t-il si le frottement agit dans la direction oppos\xe9e au mouvement ? Les \xe9l\xe8ves peuvent voir les objets d\xe9c\xe9l\xe9rer et finalement s'arr\xeater, m\xeame sans force appliqu\xe9e. Et le frottement sur une pente ? L'analyse des composantes devient intuitive quand on peut voir l'objet glisser, acc\xe9l\xe9rer ou rester immobile selon l'angle."}),(0,i.jsx)("h3",{children:"Mouvement des projectiles"}),(0,i.jsx)("p",{children:"Le mouvement des projectiles combine des composantes horizontales et verticales. Cette ind\xe9pendance est conceptuellement difficile. Beaucoup d'\xe9l\xe8ves croient que les objets \xab \xe9puisent \xbb leur quantit\xe9 de mouvement horizontale ou que la vitesse horizontale affecte le temps de chute."}),(0,i.jsx)("p",{children:"Une simulation physiquement pr\xe9cise permet aux \xe9l\xe8ves de lancer des projectiles \xe0 diff\xe9rents angles et vitesses. Ils peuvent tracer des trajectoires, mesurer les positions d'atterrissage, comparer les temps de vol. Quand ils tirent deux projectiles horizontalement \xe0 des vitesses diff\xe9rentes et les voient toucher le sol simultan\xe9ment, l'ind\xe9pendance du mouvement vertical et horizontal devient \xe9vidente."}),(0,i.jsx)("h3",{children:"Transfert et conservation d'\xe9nergie"}),(0,i.jsx)("p",{children:"La conservation de l'\xe9nergie est souvent enseign\xe9e comme une technique de calcul plut\xf4t qu'une r\xe9alit\xe9 physique. Les \xe9l\xe8ves m\xe9morisent des formules sans comprendre pourquoi l'\xe9nergie est conserv\xe9e ou o\xf9 elle va."}),(0,i.jsx)("p",{children:"Dans une simulation physiquement pr\xe9cise, les \xe9l\xe8ves peuvent suivre l'\xe9nergie pendant qu'elle se transforme. Une balle en haut d'une rampe a de l'\xe9nergie potentielle gravitationnelle. En roulant vers le bas, le potentiel se convertit en cin\xe9tique. En bas, l'\xe9nergie cin\xe9tique est maximale. S'il y a du frottement, une partie de l'\xe9nergie devient thermique. Les \xe9l\xe8ves peuvent mesurer chaque forme et v\xe9rifier que le total reste constant."}),(0,i.jsx)("p",{children:"Les collisions rendent cela encore plus clair. Les collisions \xe9lastiques conservent l'\xe9nergie cin\xe9tique. Les in\xe9lastiques non. Les \xe9l\xe8ves peuvent configurer les deux types, mesurer l'\xe9nergie avant et apr\xe8s, et d\xe9couvrir la diff\xe9rence par eux-m\xeames."}),(0,i.jsx)("h3",{children:"\xc9lectricit\xe9 et circuits"}),(0,i.jsx)("p",{children:"L'\xe9lectricit\xe9 est invisible, ce qui la rend particuli\xe8rement difficile \xe0 enseigner. Les \xe9l\xe8ves ne peuvent pas voir le courant circuler ou la tension chuter. Ils ne peuvent que les d\xe9duire des mesures."}),(0,i.jsx)("p",{children:"Une simulation de circuit physiquement pr\xe9cise rend l'invisible visible. Le courant circule selon la loi d'Ohm. Ajouter de la r\xe9sistance r\xe9duit le courant. Les branches parall\xe8les partagent le courant selon leurs rapports de r\xe9sistance. Les courts-circuits causent des probl\xe8mes. Tout cela \xe9merge de la physique, pas de r\xe9ponses programm\xe9es."}),(0,i.jsx)("p",{children:"Les \xe9l\xe8ves peuvent construire des circuits, ajouter des composants, mesurer les tensions et les courants en diff\xe9rents points. Quand leurs mesures ne correspondent pas \xe0 leurs pr\xe9dictions, ils d\xe9pannent. Ce processus de r\xe9solution de probl\xe8mes est l\xe0 o\xf9 la compr\xe9hension se d\xe9veloppe."}),(0,i.jsx)("h2",{children:"Int\xe9gration avec l'analyse de donn\xe9es"}),(0,i.jsx)("p",{children:"La physique pratique implique des donn\xe9es. Les vraies exp\xe9riences n\xe9cessitent mesure, analyse et interpr\xe9tation. Les laboratoires virtuels devraient faire de m\xeame."}),(0,i.jsx)("p",{children:"Une simulation de physique bien con\xe7ue exporte les donn\xe9es dans des formats utilisables. Les \xe9l\xe8ves peuvent enregistrer la position en fonction du temps, l'importer dans un tableur, calculer la vitesse et l'acc\xe9l\xe9ration. Ils peuvent tracer des graphiques, ajuster des courbes, extraire des grandeurs physiques. Ce sont les m\xeames comp\xe9tences qu'ils utiliseront en physique universitaire et dans les carri\xe8res scientifiques."}),(0,i.jsx)("p",{children:"Les donn\xe9es des simulations physiquement pr\xe9cises sont assez propres pour r\xe9v\xe9ler les relations sous-jacentes mais assez r\xe9alistes pour n\xe9cessiter une analyse appropri\xe9e. Les \xe9l\xe8ves apprennent \xe0 identifier les erreurs syst\xe9matiques, g\xe9rer l'incertitude de mesure et distinguer le signal du bruit."}),(0,i.jsxs)("p",{children:["La recherche sur l'apprentissage en laboratoire souligne l'analyse de donn\xe9es comme une comp\xe9tence centrale qui re\xe7oit souvent une attention insuffisante dans les laboratoires traditionnels (",(0,i.jsx)("a",{href:"https://doi.org/10.1119/1.4902381",target:"_blank",rel:"noopener noreferrer",children:"Holmes et al., 2015"}),"). Les laboratoires virtuels avec des capacit\xe9s d'exportation de donn\xe9es appropri\xe9es comblent directement cette lacune."]}),(0,i.jsx)("h2",{children:"Ce que dit la recherche"}),(0,i.jsxs)("p",{children:["Les preuves pour des simulations de physique bien con\xe7ues sont solides. Une \xe9tude \xe0 grande \xe9chelle a compar\xe9 des \xe9l\xe8ves apprenant avec des simulations PhET versus du mat\xe9riel pratique pour les circuits \xe9lectriques. Le groupe simulation a significativement mieux perform\xe9 aux \xe9valuations conceptuelles et a montr\xe9 une compr\xe9hension plus profonde des principes sous-jacents (",(0,i.jsx)("a",{href:"https://doi.org/10.1119/1.2885199",target:"_blank",rel:"noopener noreferrer",children:"Finkelstein et al., 2010"}),")."]}),(0,i.jsx)("p",{children:"Pourquoi le virtuel battrait-il le r\xe9el ? Les chercheurs ont sugg\xe9r\xe9 que les simulations \xe9liminent les barri\xe8res pratiques qui distraient des concepts physiques. Les \xe9l\xe8ves ne luttent pas avec du mat\xe9riel d\xe9fectueux, des mauvaises connexions ou des difficult\xe9s de mesure. Ils se concentrent sur la physique."}),(0,i.jsxs)("p",{children:["Les m\xe9ta-analyses confirment ces r\xe9sultats. Les simulations interactives avec une haute fid\xe9lit\xe9 physique produisent syst\xe9matiquement de meilleurs r\xe9sultats d'apprentissage que l'enseignement traditionnel ou les ressources num\xe9riques de moindre fid\xe9lit\xe9 (",(0,i.jsx)("a",{href:"https://doi.org/10.3102/0034654313499618",target:"_blank",rel:"noopener noreferrer",children:"Merchant et al., 2014"}),"). L'essentiel est que la pr\xe9cision et l'interactivit\xe9 comptent. Les animations passives ou les mod\xe8les impr\xe9cis n'offrent pas les m\xeames avantages."]}),(0,i.jsx)("h2",{children:"Comment WhimsyLabs fait la physique"}),(0,i.jsx)("p",{children:"WhimsyLabs a construit notre plateforme de laboratoire virtuel sur une architecture physique-d'abord. Chaque interaction, du l\xe2cher d'une balle au c\xe2blage d'un circuit, passe par notre moteur physique. Rien n'est pr\xe9cuit. Rien n'est anim\xe9. Tout est calcul\xe9."}),(0,i.jsx)("p",{children:"Les \xe9l\xe8ves vivent de vraies cons\xe9quences physiques. S'ils configurent une exp\xe9rience incorrectement, ils obtiennent des r\xe9sultats incorrects. Notre tuteur IA, WhimsyCat, peut les guider vers la compr\xe9hension du pourquoi, mais il ne corrige pas secr\xe8tement leurs erreurs. L'apprentissage vient de l'engagement avec la vraie physique, pas du suivi d'un script pr\xe9d\xe9termin\xe9."}),(0,i.jsx)("p",{children:"Les enseignants obtiennent des donn\xe9es d\xe9taill\xe9es sur ce que les \xe9l\xe8ves ont fait et quels r\xe9sultats ils ont observ\xe9s. Ce n'est pas juste du suivi de compl\xe9tion. C'est une v\xe9ritable vision de la compr\xe9hension des \xe9l\xe8ves bas\xe9e sur leur fa\xe7on d'interagir avec les syst\xe8mes physiques."}),(0,i.jsx)("p",{children:"Nos exp\xe9riences de physique couvrent la m\xe9canique, l'\xe9lectricit\xe9, les ondes et l'\xe9nergie. Chacune produit de vraies mesures que les \xe9l\xe8ves peuvent analyser, repr\xe9senter graphiquement et interpr\xe9ter. Les comp\xe9tences se transf\xe8rent directement au travail de laboratoire physique et au-del\xe0."}),(0,i.jsx)("h2",{children:"Voyez-le en action"}),(0,i.jsx)("p",{children:"Les mots ne peuvent d\xe9crire qu'une partie. La physique se comprend mieux par l'exp\xe9rience."}),(0,i.jsxs)("p",{children:["Si vous enseignez la physique et voulez voir ce qu'un v\xe9ritable moteur de simulation physique peut faire, ",(0,i.jsx)("a",{href:"/contact",children:"demandez une d\xe9mo"}),". Nous vous montrerons des exp\xe9riences o\xf9 la physique fonctionne vraiment, o\xf9 les erreurs des \xe9l\xe8ves produisent de vraies cons\xe9quences, et o\xf9 l'analyse de donn\xe9es r\xe9v\xe8le de vraies relations physiques."]}),(0,i.jsx)("p",{children:"Vos \xe9l\xe8ves m\xe9ritent des simulations qui enseignent les bonnes intuitions. WhimsyLabs les fournit."}),(0,i.jsxs)("div",{className:"references-section",children:[(0,i.jsx)("h3",{children:"R\xe9f\xe9rences"}),(0,i.jsxs)("ul",{className:"references-list",children:[(0,i.jsxs)("li",{children:["de Jong, T., Linn, M. C., & Zacharia, Z. C. (2013). Physical and virtual laboratories in science and engineering education.",(0,i.jsx)("em",{children:" Science"}),", 340(6130), 305-308.",(0,i.jsx)("a",{href:"https://doi.org/10.1103/PhysRevPhysEducRes.13.010124",target:"_blank",rel:"noopener noreferrer",children:" https://doi.org/10.1103/PhysRevPhysEducRes.13.010124"})]},"ref-1"),(0,i.jsxs)("li",{children:["Finkelstein, N. D., Adams, W. K., Keller, C. J., Kohl, P. B., Perkins, K. K., Podolefsky, N. S., ... & LeMaster, R. (2005). When learning about the real world is better done virtually: A study of substituting computer simulations for laboratory equipment.",(0,i.jsx)("em",{children:" Physical Review Special Topics - Physics Education Research"}),", 1(1), 010103.",(0,i.jsx)("a",{href:"https://doi.org/10.1119/1.2150754",target:"_blank",rel:"noopener noreferrer",children:" https://doi.org/10.1119/1.2150754"})]},"ref-2"),(0,i.jsxs)("li",{children:["Finkelstein, N. D., Adams, W. K., Keller, C. J., Kohl, P. B., Perkins, K. K., Podolefsky, N. S., & Reid, S. (2010). When learning about the real world is better done virtually: A study of substituting computer simulations for laboratory equipment.",(0,i.jsx)("em",{children:" Physical Review Special Topics - Physics Education Research"}),", 6(1), 020108.",(0,i.jsx)("a",{href:"https://doi.org/10.1119/1.2885199",target:"_blank",rel:"noopener noreferrer",children:" https://doi.org/10.1119/1.2885199"})]},"ref-3"),(0,i.jsxs)("li",{children:["Hestenes, D., Wells, M., & Swackhamer, G. (1992). Force concept inventory.",(0,i.jsx)("em",{children:" The Physics Teacher"}),", 30(3), 141-158.",(0,i.jsx)("a",{href:"https://doi.org/10.1119/1.2343497",target:"_blank",rel:"noopener noreferrer",children:" https://doi.org/10.1119/1.2343497"})]},"ref-4"),(0,i.jsxs)("li",{children:["Holmes, N. G., Wieman, C. E., & Bonn, D. A. (2015). Teaching critical thinking.",(0,i.jsx)("em",{children:" Proceedings of the National Academy of Sciences"}),", 112(36), 11199-11204.",(0,i.jsx)("a",{href:"https://doi.org/10.1119/1.4902381",target:"_blank",rel:"noopener noreferrer",children:" https://doi.org/10.1119/1.4902381"})]},"ref-5"),(0,i.jsxs)("li",{children:["Merchant, Z., Goetz, E. T., Cifuentes, L., Keeney-Kennicutt, W., & Davis, T. J. (2014). Effectiveness of virtual reality-based instruction on students' learning outcomes in K-12 and higher education: A meta-analysis.",(0,i.jsx)("em",{children:" Computers & Education"}),", 70, 29-40.",(0,i.jsx)("a",{href:"https://doi.org/10.3102/0034654313499618",target:"_blank",rel:"noopener noreferrer",children:" https://doi.org/10.3102/0034654313499618"})]},"ref-6")]})]}),(0,i.jsx)("h2",{children:"Pour aller plus loin"}),(0,i.jsxs)("ul",{children:[(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/science-real-time-physics-simulations-virtual-labs",children:"La physique en temps r\xe9el dans les laboratoires virtuels : Rendre l'apprentissage amusant"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/why-traditional-virtual-labs-fail-physics-engine",children:"Pourquoi les laboratoires virtuels traditionnels \xe9chouent : Le probl\xe8me du moteur physique"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/sandbox-learning-revolution-stem-education",children:"La r\xe9volution de l'apprentissage bac \xe0 sable : Pourquoi la libert\xe9 d'\xe9chouer est essentielle"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/teachers-are-experts-custom-experiment-designer",children:"Les enseignants sont les experts : Concepteur d'exp\xe9riences personnalis\xe9es"})})]})]})}}]);
